// Generated by GitHub Copilot - Oct-23-2026
import { useEffect, useRef, useState } from 'react';
import type { DispenseStage, Mood, Recipe } from '../../types';
import { generateRecipeImage } from '../../services/ai';
import { dispenseRecipe } from '../../services/dispenser';
import GeneratedArt from '../../components/GeneratedArt';
import JellyBean from '../../components/JellyBean';

interface Props {
  recipe: Recipe;
  mood: Mood;
  dispenserId: string | null;
  onBack: () => void;
  onRestart: () => void;
}

const STAGE_LABELS: Record<DispenseStage, string> = {
  queued: 'Sending recipe to dispenser',
  aligning: 'Aligning canisters',
  dispensing: 'Dispensing beans',
  complete: 'Enjoy your new flavor!',
};
const STAGE_ORDER: DispenseStage[] = ['queued', 'aligning', 'dispensing', 'complete'];

/** Digital recipe card: AI title, description, ingredients and big photo, then Finalize to dispense. */
export default function RecipeCard({ recipe, mood, dispenserId, onBack, onRestart }: Props) {
  const abortRef = useRef<AbortController | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(true);
  const [stage, setStage] = useState<DispenseStage | null>(null);

  useEffect(() => {
    let cancelled = false;
    generateRecipeImage(recipe).then((url) => {
      if (cancelled) return;
      setImageUrl(url);
      setImageLoading(false);
    });
    return () => {
      cancelled = true;
      abortRef.current?.abort();
    };
  }, [recipe]);

  const busy = stage !== null && stage !== 'complete';
  const totalBeans = recipe.ingredients.reduce((n, i) => n + i.count, 0);

  const finalize = async () => {
    if (!dispenserId) return;
    abortRef.current = new AbortController();
    await dispenseRecipe(dispenserId, recipe, setStage, abortRef.current.signal);
  };

  return (
    <section className="recipe-sheet-wrap" aria-labelledby="recipe-card-title">
      <article className="recipe-sheet">
        <div className="recipe-sheet__info">
          <p className="eyebrow eyebrow--purple">New flavor unlocked</p>
          <h1 id="recipe-card-title">{recipe.name}</h1>
          <span className="chip chip--mood chip--sm">{mood.name}</span>
          <p className="recipe-sheet__desc">{recipe.description}</p>

          <div className="new-flavor">
            <h2 className="new-flavor__name">{recipe.newFlavorName}</h2>
            <p>{recipe.newFlavorNotes}</p>
          </div>

          <h2 className="recipe-sheet__subhead">Recipe · {totalBeans} beans</h2>
          <ul className="ingredients">
            {recipe.ingredients.map((ing) => (
              <li key={ing.flavor.id} className="ingredient">
                <JellyBean color={ing.flavor.color} size={40} />
                <span className="ingredient__name">{ing.flavor.name}</span>
                <span className="ingredient__count">×{ing.count}</span>
              </li>
            ))}
          </ul>

          {stage && (
            <ol className="dispense-steps" aria-label="Dispense progress">
              {STAGE_ORDER.map((s, idx) => {
                const cur = STAGE_ORDER.indexOf(stage);
                const state = idx < cur || stage === 'complete' ? 'done' : idx === cur ? 'active' : 'todo';
                return (
                  <li key={s} className={`dispense-step dispense-step--${state}`}>
                    <span className="dispense-step__dot" aria-hidden="true" />
                    {STAGE_LABELS[s]}
                    {state === 'done' && <span className="sr-only"> (done)</span>}
                  </li>
                );
              })}
            </ol>
          )}
          <p className="sr-only" role="status">
            {stage ? STAGE_LABELS[stage] : ''}
          </p>
        </div>

        <div className="recipe-sheet__art">
          {imageLoading ? (
            <div className="recipe-sheet__loading" role="status">
              <span className="spinner" aria-hidden="true" />
              Generating your recipe photo...
            </div>
          ) : imageUrl ? (
            <img src={imageUrl} alt={`AI-generated photo of ${recipe.name}`} />
          ) : (
            <GeneratedArt recipe={recipe} label={`AI-generated artwork for ${recipe.name}`} />
          )}
        </div>
      </article>

      <div className="nav-buttons">
        {stage === 'complete' ? (
          <button type="button" className="btn btn--primary btn--purple" onClick={onRestart}>
            Mix another
          </button>
        ) : (
          <>
            <button type="button" className="btn btn--outline" disabled={busy} onClick={onBack}>
              Back
            </button>
            <button
              type="button"
              className="btn btn--primary btn--purple"
              disabled={busy || imageLoading || !dispenserId}
              onClick={finalize}
            >
              {busy ? 'Dispensing...' : 'Finalize'}
            </button>
          </>
        )}
      </div>
    </section>
  );
}
